import numpy as np

# True prices (thousands) and two models' predictions for 6 houses
actual = np.array([250, 340, 160, 520, 300, 410], dtype=float)
model_a = np.array([225, 365, 135, 545, 275, 435], dtype=float)  # six even misses of 25
model_b = np.array([250, 340, 160, 400, 300, 410], dtype=float)  # one big miss

def mae(y, y_hat):
    return np.mean(np.abs(y - y_hat))

def mse(y, y_hat):
    return np.mean((y - y_hat) ** 2)

def rmse(y, y_hat):
    return np.sqrt(mse(y, y_hat))

for name, preds in [("model A", model_a), ("model B", model_b)]:
    print(f"{name}: MAE={mae(actual, preds):6.1f}  "
          f"MSE={mse(actual, preds):8.1f}  RMSE={rmse(actual, preds):6.1f}")

# Model B has the lower MAE (one miss of 120 vs six misses of 25),
# but the higher RMSE, because squaring punishes the single big miss.

# Gradient of MSE with respect to the prediction, used by gradient descent:
# d/d(pred) of mean((y - pred)^2) = -2 * mean(y - pred)
error = actual - model_b
print("MSE gradient wrt prediction (model B):", (-2 * np.mean(error)).round(3))

import numpy as np

def top_k(index: np.ndarray, query_vec: np.ndarray, chunks: list[str],
          k: int = 5, min_score: float | None = None):
    """index: (N, d) unit vectors; query_vec: (d,) unit vector."""
    scores = index @ query_vec
    order = np.argsort(scores)[::-1][:k]
    results = []
    for i in order:
        if min_score is not None and scores[i] < min_score:
            break                      # ranking is sorted, so stop early
        results.append({"text": chunks[i], "score": float(scores[i])})
    return results

# Quick evaluation harness: does the expected chunk land in the top k?
def recall_at_k(index, encode, chunks, test_set, k):
    hits = 0
    for question, expected_substring in test_set:
        hits_for_q = top_k(index, encode(question), chunks, k)
        if any(expected_substring in r["text"] for r in hits_for_q):
            hits += 1
    return hits / len(test_set)

