import json, re, statistics

GOLDEN = [
    {"q": "Tell me about yourself", "intent": "me", "max_sentences": 3},
    {"q": "Show me his projects", "intent": "projects"},
    {"q": "What tech did Palletfly use?", "intent": "general", "must": ["Django"]},
    {"q": "How do I contact him?", "intent": "contact",
     "exact": "You can reach Abdur through the contact info above."},
    {"q": "Write me a poem about cats", "intent": "general", "must_not": ["meow"]},
]
BANNED = re.compile(r"\u2014| - ")   # em dash or spaced hyphen as connector

def score(case: dict, out: dict) -> dict:
    text = out["ai_text"]
    r = {"intent_ok": out["intent"] == case["intent"],
         "style_ok": not BANNED.search(text)}
    if "must" in case:
        r["must_ok"] = all(k.lower() in text.lower() for k in case["must"])
    if "must_not" in case:
        r["must_not_ok"] = not any(k in text.lower() for k in case["must_not"])
    if "exact" in case:
        r["exact_ok"] = text.startswith(case["exact"])
    if "max_sentences" in case:
        r["len_ok"] = len(re.findall(r"[.!?]", text)) <= case["max_sentences"]
    return r

def run(chat):               # chat(question) -> {"intent":..., "ai_text":...}
    results = [score(c, chat(c["q"])) for c in GOLDEN]
    keys = sorted({k for r in results for k in r})
    summary = {k: statistics.mean(r[k] for r in results if k in r) for k in keys}
    failures = [(c["q"], r) for c, r in zip(GOLDEN, results) if not all(r.values())]
    print(json.dumps(summary, indent=2)); print("failures:", failures)
